scripts.lcg_update:
def solve(inputs: dict) -> float:
    SEED = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    X = SEED
    for i in range(K):
        X = (A * X + B) % M

    return float(X)

scripts.modexp:
def solve(inputs: dict) -> float:
    BASE = inputs['BASE']
    EXP = inputs['EXP']
    MOD = inputs['MOD']

    result = pow(BASE, EXP, MOD)

    return float(result)

scripts.dot_product:
def solve(inputs: dict) -> float:
    quantities = inputs['QUANTITIES']
    prices = inputs['PRICES']

    total = sum(q * p for q, p in zip(quantities, prices))

    return float(total)

